"""
Runs tools/benchmark_draws.bb in each layout and prints a table of draw calls, state changes and milliseconds per frame.

    python3 tools/benchmark_draws.py [path to blitzcc] [layout ...]

Without a display the programs run under xvfb-run, which with Mesa means llvmpipe: the times are then mostly the CPU
rasterizing and only good for comparing one build with another, while the counts (what the GPU is told to do) are exact.
"""
import os
import re
import shutil
import subprocess
import sys
import tempfile
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "."))
import procutil  # noqa: E402

LAYOUTS = ["copies", "unique", "textured", "large", "blended", "offscreen", "mixed"]


def main():
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    args = sys.argv[1:]
    compiler = args.pop(0) if args and os.path.isfile(args[0]) else os.path.join(root, "build", "code_compiler", "blitzcc")
    layouts = args or LAYOUTS
    runner = [] if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY") else ["xvfb-run", "-a"]
    if runner and not shutil.which("xvfb-run"):
        sys.exit("There is no display and no xvfb-run.")
    with tempfile.TemporaryDirectory() as directory:
        program = os.path.join(directory, "benchmark")
        procutil.run([compiler, os.path.join(root, "tools", "benchmark_draws.bb"), "-o", program], check=True, stdout=subprocess.DEVNULL)
        env = dict(os.environ, BENCH_FRAMES=os.environ.get("BENCH_FRAMES", "10"))
        print("%-10s %9s %7s %10s %9s %8s %10s" % ("layout", "tris", "draws", "pipelines", "textures", "buffers", "ms/frame"))
        for layout in layouts:
            env["BENCH_LAYOUT"] = layout
            result = procutil.run(runner + [program], env=env, capture_output=True, text=True, timeout=600)
            line = (result.stdout + result.stderr).strip().splitlines()[-1] if (result.stdout + result.stderr).strip() else ""
            values = dict(re.findall(r"(\w+)=([\d.]+)", line))
            if "draws" not in values:
                print("%-10s failed: %s" % (layout, line or "no output"))
                continue
            print("%-10s %9s %7s %10s %9s %8s %10.1f" % (layout, values["tris"], values["draws"], values["pipelines"], values["textures"], values["buffers"], float(values["ms_per_frame"])))


main()
